(()=>{
'use strict';
let data=null,loading=null;
const URL='ffws-br-2026-s2/home-results.json';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const shortTeam=name=>({
  'LOUD SNICKERS':'LOUD','FLUXO W7M':'FX','RISE GAMING':'RISE','RUSH GAMING':'RUSH',
  'TEAM SOLID':'TS','AFROGAMES':'AFG','SX TET':'SX','CPT VOX':'CPT','ALPHA7':'A7',
  'INFLUENCE RAGE':'INF','FURY UNITED':'FURY','AXS FUSION':'AXS','HAWK GAMING':'HAWK'
}[String(name||'').toUpperCase()]||String(name||''));
const fmt=n=>Number(n||0).toLocaleString('pt-BR');
async function load(){
  if(data)return data;
  if(loading)return loading;
  loading=fetch(URL,{cache:'no-cache'})
    .then(r=>r.ok?r.json():Promise.reject(new Error('HTTP '+r.status)))
    .then(v=>data=v)
    .catch(()=>data={teams:[],players:[],rankings:{kills:[],damage:[],assists:[]},status:'upcoming'})
    .finally(()=>loading=null);
  return loading;
}
function placeholder(text,cols=4){return `<tr><td colspan="${cols}" class="home-rank-placeholder">${esc(text)}</td></tr>`}
function teamRows(rows){
  return rows.length?rows.slice(0,6).map((r,i)=>`<tr>
    <td class="home-rank-pos">${i+1}</td>
    <td class="home-rank-main"><a href="equipe.html?time=${encodeURIComponent(r.team)}">${esc(shortTeam(r.team))}</a><small>${Number(r.matches||0)} Q</small></td>
    <td class="home-rank-number home-rank-points">${fmt(r.points)}</td>
    <td class="home-rank-number">${fmt(r.kills)}</td>
  </tr>`).join(''):placeholder('Classificação disponível após as primeiras quedas.');
}
function playerRows(rows,metric){
  return rows.length?rows.slice(0,6).map((r,i)=>`<tr>
    <td class="home-rank-pos">${i+1}</td>
    <td class="home-rank-main"><a href="jogador.html?jogador=${encodeURIComponent(r.player||r.name||'')}&time=${encodeURIComponent(r.team||'')}">${esc(r.player||r.name||'')}</a><small>${esc(shortTeam(r.team||''))}</small></td>
    <td class="home-rank-number">${fmt(r[metric])}</td>
    <td class="home-rank-number home-rank-matches">${Number(r.matches||0)}</td>
  </tr>`).join(''):placeholder('Ranking disponível após as primeiras quedas.');
}
function renderRows(payload){
  const rankings=payload.rankings||{};
  const kills=rankings.kills||payload.players||[];
  const targets=[
    ['home-tbody-teams',teamRows(payload.teams||[])],
    ['home-tbody-players',playerRows(kills,'kills')],
    ['home-tbody-damage',playerRows(rankings.damage||[],'damage')],
    ['home-tbody-assists',playerRows(rankings.assists||[],'assists')]
  ];
  targets.forEach(([id,html])=>{const el=document.getElementById(id);if(el)el.innerHTML=html});
}
window.cffHomeRenderFinalStats=function(){renderRows(data||{teams:[],players:[],rankings:{}});load().then(renderRows);return true};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>load().then(renderRows),{once:true});else load().then(renderRows);
})();
